select public.consent_test_assert(not has_table_privilege('eps_oauth_consent_owner','auth.oauth_authorizations','SELECT')and not has_column_privilege('eps_oauth_consent_owner','auth.oauth_authorizations','authorization_code','SELECT')and not has_column_privilege('eps_oauth_consent_owner','auth.oauth_authorizations','state','SELECT')and not has_column_privilege('eps_oauth_consent_owner','auth.oauth_authorizations','code_challenge','SELECT')and not has_column_privilege('eps_oauth_consent_owner','auth.oauth_clients','client_secret_hash','SELECT'),'owner has metadata columns only');
select public.consent_test_assert(not has_column_privilege('eps_oauth_consent_owner','auth.oauth_authorizations','authorization_id','SELECT')and not has_column_privilege('eps_oauth_consent_owner','auth.oauth_clients','id','SELECT')and not has_table_privilege('postgres','auth.oauth_authorizations','SELECT WITH GRANT OPTION')and not has_table_privilege('postgres','auth.oauth_clients','SELECT WITH GRANT OPTION'),'faithful managed owner authority and no direct OAuth reads');
select public.consent_test_assert(has_function_privilege('postgres','eps.oauth_consent_browser_session()','EXECUTE')and has_function_privilege('eps_oauth_consent_owner','eps.oauth_consent_binding(text,text)','EXECUTE'),'bridge can execute ordinary-session guard and coordinator can execute bridge');
