select public.consent_test_assert(exists(select 1 from pg_roles where rolname='eps_oauth_consent_owner'and not rolcanlogin and not rolsuper and not rolinherit and not rolbypassrls and not rolcreaterole and not rolcreatedb and not rolreplication),'owner role least privilege');
