select public.consent_test_assert(exists(select 1 from pg_policy where polrelid='auth.sessions'::regclass and polname='preserved_auth_session_policy')and(select relrowsecurity and not relforcerowsecurity from pg_class where oid='auth.sessions'::regclass)and(select not relrowsecurity from pg_class where oid='auth.oauth_authorizations'::regclass),'managed RLS and previous policy preserved');
